// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount, bool shouldFail) public {
        vm.assume(amount > 0);
        // Deploy a helper that either succeeds or reverts on value transfer
        ConditionalReceiver receiver = new ConditionalReceiver(shouldFail);
        address actor = address(receiver);
        vm.deal(actor, amount);
        // Deposit as the adversarial receiver
        vm.prank(actor);
        c.deposit{value: amount}();
        // Attempt withdrawal to self
        bool withdrawReverted = false;
        try c.withdrawAll() {
        } catch {
            withdrawReverted = true;
        }
        uint256 creditAfter = c.credit(actor);
        // The invariant: if the low-level call inside withdrawAll fails and the transaction does NOT revert
        // (i.e., the mut bug clears credit despite failure), credit must remain > 0.
        // With correct C, either the whole tx reverts (credit unchanged > 0) or the call succeeds (credit == 0).
        // In the bug, a failed call leads to credit == 0 without revert.
        bool invariantHolds = !(creditAfter == 0 && (shouldFail && !withdrawReverted));
        assertTrue(invariantHolds);
    }
}

contract ConditionalReceiver {
    bool immutable revertOnReceive;
    constructor(bool _revert) { revertOnReceive = _revert; }
    receive() external payable {
        if (revertOnReceive) revert("forced revert");
    }
}

