pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;
    function setUp() public {
        c = new C();
        reverter = new Reverter();
    }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // keep amounts reasonable and non-zero
        vm.assume(depositAmount > 0 && depositAmount < 1 ether);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);
        // actor is the reverter (adversarial callee that fails on receive)
        address actor = address(reverter);
        // deposit: some other EOA sends funds on behalf of actor
        address donor = address(0x1234);
        vm.deal(donor, depositAmount);
        vm.prank(donor);
        c.deposit{value: depositAmount}();
        // ensure the actor's credit equals the deposit amount
        uint256 creditBefore = c.credit(actor);
        vm.assume(creditBefore == depositAmount);
        // during withdrawAll, the low-level call to reverter will revert
        // but the buggy code resets credit to 0 anyway
        vm.prank(actor);
        (bool success, ) = address(c).call{value: withdrawAmount}(abi.encodeWithSignature("withdrawAll()"));
        // the correct contract reverts the whole call (success == false),
        // the buggy one does not revert and credit becomes 0
        uint256 creditAfter = c.credit(actor);
        assertTrue(success ? creditAfter == 0 : creditAfter == creditBefore);
    }
}

