        uint256 balanceBefore = address(c).balance;
        uint256 creditOtherUserBefore = c.credit(otherUser);
        uint256 creditAttackerBefore = c.credit(attackerAddr);

        // Attacker calls withdrawAll, which triggers reentrancy in buggy version
        vm.prank(attackerAddr);
        try c.withdrawAll() { } catch { }

