pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawCallerSeed) public {
        // Keep deposit amount in a reasonable range
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        // Derive an external actor address from the seed
        address actor = address(uint160(withdrawCallerSeed));
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // Deploy a helper that reverts on receiving Ether (failing callee)
        Reverter reverter = new Reverter();

        // Fund the actor and make a deposit into C
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Compute sum of credits and contract balance before withdrawal
        uint256 creditBefore = c.credit(actor);
        uint256 balanceBefore = address(c).balance;

        // Verify invariant holds before withdrawal
        assertTrue(creditBefore == balanceBefore, "precondition: credit != balance");

        // Now make the actor attempt a withdrawal, but with a failing external callee.
        // We cannot directly change who receives the call in withdrawAll (msg.sender),
        // but we can make the actor's call to withdrawAll fail.
        // However, withdrawAll always calls msg.sender, which is actor (an EOA),
        // and low-level call to an EOA always succeeds.
        // The adversarial counter-party rule requires a different approach:
        // We deploy a "reverter" address and make it the caller?
        // The contract C always sends funds to msg.sender. To trigger a failing call,
        // msg.sender must be a contract that reverts in its receive.
        // So we need a helper that initiates the call to withdrawAll and reverts on receiving Ether.
        // We deploy an Attacker that calls c.withdrawAll() and has a reverting receive.
        Attacker attacker = new Attacker(c);
        // Deposit into C from the attacker's address
        vm.deal(address(attacker), depositAmount);
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        // Record state after deposit
        uint256 attackerCreditBefore = c.credit(address(attacker));
        uint256 totalCreditBefore = attackerCreditBefore + c.credit(actor);
        uint256 balanceAfterDeposit = address(c).balance;

        // Try the withdrawal via the attacker
        bool success;
        try attacker.triggerWithdraw() {
            success = true;
        } catch {
            success = false;
        }

        // After the attempt, compute sum of all credits
        uint256 totalCreditAfter = c.credit(address(attacker)) + c.credit(actor);
        uint256 balanceAfter = address(c).balance;

        // The invariant: total balance == total credit.
        // In the reference C, the modifier lock reentrancy prevents reentrancy,
        // but more importantly, if the external call reverts, the whole withdrawal reverts,
        // leaving credit unchanged. In the lack-of-modifier-body mutant,
        // the critical part is that the modifier is empty, removing reentrancy protection.
        // The failing call setup tests whether the contract handles the revert correctly.
        // However, the previously tried properties focused on reentrancy.
        // This property checks that a failing external call does NOT alter state,
        // which should hold in reference but may fail if the lock logic is missing.
        // Actually, the lock modifier only guards reentrancy, not state rollback.
        // The try/catch observes if withdrawAll reverts; if it reverts, credits should be unchanged.
        // If success == false, then totalCreditAfter must equal totalCreditBefore.
        if (!success) {
            assertTrue(totalCreditAfter == totalCreditBefore, "credit changed on failed withdrawal");
        }
    }
}

